      introAbout: 'Cyclische groepen maakt van een groep een ring van kralen, één kraal per element. Kies een modulus en een bewerking — optelling modulo n, of vermenigvuldiging van de eenheden modulo n — en kies dan een element: zijn koorden lopen rond de ring, en als ze elke kraal bereiken, brengt dat element de hele groep voort en is de groep cyclisch. De ring vult het scherm, met de bedieningselementen van de groep erboven. De numerieke lijst toont de subgroep die elk element voortbrengt, en een isomorfe groep kan naast de ring worden geopend en er met het hangslot aan worden vergrendeld, zodat de twee als één draaien, kleuren en oplichten.',
      introFullscreen: 'Omdat deze tool zoveel bedieningselementen heeft, is het eigenlijk een toepassing voor volledig scherm. Hij werkt het best in volledig scherm, en de gewone kop van de website is hoe dan ook verborgen. Gebruik de knoppen Vorige en Volgende van je browser in plaats van de kop om terug te gaan naar de rest van de website. Veel plezier!',
