      isoLockOpenSub: 'Doppelklick, um die Gruppen über den Isomorphismus von Untergruppe zu Gruppe zu sperren',
      introAbout: 'Zyklische Gruppen macht aus einer Gruppe einen Ring aus Perlen, eine Perle für jedes Element. Wähle einen Modulus und eine Verknüpfung — Addition modulo n oder Multiplikation der Einheiten modulo n — und dann ein Element: Seine Sehnen laufen um den Ring, und wenn sie jede Perle erreichen, erzeugt dieses Element die ganze Gruppe, was die Gruppe zyklisch macht. Der Ring füllt den Bildschirm, darüber die Bedienelemente der Gruppe. Die numerische Liste zeigt die Untergruppe, die jedes Element erzeugt, und eine isomorphe Gruppe lässt sich neben dem Ring öffnen und mit dem Vorhängeschloss an ihn koppeln, sodass sich beide gemeinsam drehen, färben und hervorheben.',
      introFullscreen: 'Weil dieses Werkzeug so viele Bedienelemente hat, ist es eigentlich eine Vollbildanwendung. Am besten nutzt du es im Vollbild, und die übliche Kopfzeile der Website ist so oder so ausgeblendet. Um zum Rest der Website zurückzukehren, nutze statt der Kopfzeile die Zurück- und Vorwärts-Schaltflächen deines Browsers. Viel Spaß!',
