      introAbout: 'Grupos cíclicos convierte un grupo en un círculo de cuentas, una cuenta por cada elemento. Elige un módulo y una operación — la suma módulo n, o la multiplicación de las unidades módulo n — y después un elemento: sus cuerdas recorren el círculo, y cuando alcanzan todas las cuentas, ese elemento genera el grupo entero, lo que hace cíclico al grupo. El círculo llena la pantalla, con los controles del grupo encima. La lista numérica muestra el subgrupo que genera cada elemento, y se puede abrir un grupo isomorfo junto al círculo y bloquearlo con el candado, para que los dos giren, se coloreen y se resalten a la vez.',
      introFullscreen: 'Como esta herramienta tiene tantos controles, en realidad es una aplicación de pantalla completa. Se usa mejor en pantalla completa, y la cabecera habitual del sitio queda oculta en cualquier caso. Para volver al resto del sitio, usa los botones Atrás y Adelante de tu navegador en lugar de la cabecera. ¡Que te diviertas!',
