      introAbout: 'Gruppi ciclici trasforma un gruppo in un cerchio di perline, una perlina per ogni elemento. Scegli un modulo e un’operazione — l’addizione modulo n, o la moltiplicazione delle unità modulo n — poi scegli un elemento: le sue corde girano intorno al cerchio, e quando raggiungono ogni perlina quell’elemento genera l’intero gruppo, il che rende il gruppo ciclico. Il cerchio riempie lo schermo, con i comandi del gruppo sopra. L’elenco numerico mostra il sottogruppo generato da ogni elemento, e un gruppo isomorfo può essere aperto accanto al cerchio e bloccato a esso con il lucchetto, così i due ruotano, si colorano e si evidenziano insieme.',
      introFullscreen: 'Poiché questo strumento ha così tanti comandi, è in realtà un’applicazione a schermo intero. Si usa al meglio a schermo intero, e l’intestazione abituale del sito è comunque nascosta. Per tornare al resto del sito, usa i pulsanti Indietro e Avanti del browser invece dell’intestazione. Buon divertimento!',
