      introAbout: 'Grupos cíclicos transforma um grupo num círculo de contas, uma conta por cada elemento. Escolhe um módulo e uma operação — adição módulo n ou multiplicação das unidades módulo n — e depois escolhe um elemento: as suas cordas percorrem o círculo e, quando chegam a todas as contas, esse elemento gera o grupo inteiro, o que torna o grupo cíclico. O círculo ocupa o ecrã, com os controlos do grupo por cima. A lista numérica mostra o subgrupo que cada elemento gera, e um grupo isomorfo pode ser aberto ao lado do círculo e bloqueado a ele com o cadeado, para que os dois rodem, se colorem e se destaquem como um só.',
