      introAbout: 'Cykliska grupper gör om en grupp till en ring av pärlor, en pärla för varje element. Välj en modul och en operation — addition modulo n eller multiplikation av enheterna modulo n — och välj sedan ett element: dess kordor vandrar runt ringen, och när de når varje pärla genererar elementet hela gruppen, vilket gör gruppen cyklisk. Ringen fyller skärmen med gruppens kontroller ovanför. Den numeriska listan visar delgruppen som varje element genererar, och en isomorf grupp kan öppnas bredvid ringen och låsas till den med hänglåset, så att de två roterar, färgas och markeras som en.',
      introFullscreen: 'Eftersom det här verktyget har så många kontroller är det egentligen ett helskärmsprogram. Det används bäst i helskärm, och webbplatsens vanliga sidhuvud är dolt i båda fallen. Använd webbläsarens Bakåt- och Framåt-knappar i stället för sidhuvudet för att komma tillbaka till resten av webbplatsen. Ha det så kul!',
