      introAbout: 'Sykliske grupper gjør en gruppe om til en ring av perler, én perle for hvert element. Velg en modul og en operasjon — addisjon modulo n eller multiplikasjon av enhetene modulo n — og velg så et element: kordene vandrer rundt ringen, og når de når hver perle, genererer elementet hele gruppen, noe som gjør gruppen syklisk. Ringen fyller skjermen, med gruppens kontroller over seg. Den numeriske listen viser undergruppen hvert element genererer, og en isomorf gruppe kan åpnes ved siden av ringen og låses til den med hengelåsen, slik at de to roterer, fargelegges og utheves som én.',
      introFullscreen: 'Fordi dette verktøyet har så mange kontroller, er det egentlig et fullskjermprogram. Det brukes best i fullskjerm, og nettstedets vanlige toppfelt er skjult uansett. For å komme tilbake til resten av nettstedet bruker du nettleserens Tilbake- og Fram-knapper i stedet for toppfeltet. Ha det gøy!',
