      isoLockOpenGroup: 'समूहों को उनकी समूह-से-समूह तुल्याकारिता के ज़रिए लॉक करने के लिए डबल-क्लिक करें',
      isoLockOpenSub: 'समूहों को उपसमूह-से-समूह तुल्याकारिता के ज़रिए लॉक करने के लिए डबल-क्लिक करें',
      introAbout: 'चक्रीय समूह किसी समूह को मनकों के छल्ले में बदल देता है, हर अवयव के लिए एक मनका। एक मापांक और एक संक्रिया चुनें — n के मापांक में जोड़, या n के मापांक में इकाइयों का गुणा — फिर एक अवयव चुनें: उसकी जीवाएँ छल्ले के चारों ओर चलती हैं, और जब वे हर मनके तक पहुँच जाती हैं तो वह अवयव पूरे समूह को जनित करता है, जिससे समूह चक्रीय बनता है। छल्ला पूरी स्क्रीन भर देता है और उसके ऊपर समूह के नियंत्रण रहते हैं। संख्यात्मक सूची दिखाती है कि हर अवयव कौन-सा उपसमूह जनित करता है, और किसी तुल्याकारी समूह को छल्ले के बगल में खोलकर ताले से उसके साथ लॉक किया जा सकता है, ताकि दोनों एक साथ घूमें, रंगे जाएँ और उजागर हों।',
      introFullscreen: 'इस टूल में इतने सारे नियंत्रण हैं कि यह असल में एक पूर्ण-स्क्रीन ऐप्लिकेशन है। इसे पूर्ण स्क्रीन में इस्तेमाल करना सबसे अच्छा है, और वेबसाइट का सामान्य हेडर दोनों ही स्थितियों में छिपा रहता है। वेबसाइट के बाकी हिस्से पर लौटने के लिए हेडर के बजाय अपने ब्राउज़र के पीछे और आगे वाले बटन इस्तेमाल करें। मज़े करें!',
