      introAbout: '循环群工具把一个群变成一圈珠子，每个元素一颗珠子。选择一个模数和一种运算——模 n 加法，或模 n 单位的乘法——然后选一个元素：它的弦会绕着圆环行进，当它们到达每一颗珠子时，这个元素就生成了整个群，这个群也因此是循环群。圆环占满屏幕，群的控件位于其上方。数值列表显示每个元素生成的子群；还可以在圆环旁打开一个同构的群，并用挂锁把它与圆环锁定，使两者一起旋转、着色和高亮。',
