      introAbout: 'Grup Siklik mengubah sebuah grup menjadi cincin manik-manik, satu manik untuk setiap elemen. Pilih modulus dan operasi — penjumlahan modulo n, atau perkalian unit modulo n — lalu pilih sebuah elemen: tali busurnya berjalan mengelilingi cincin, dan ketika mencapai setiap manik, elemen itu membangkitkan seluruh grup, yang membuat grup menjadi siklik. Cincin memenuhi layar dengan kontrol grup di atasnya. Daftar Numerik menampilkan subgrup yang dibangkitkan setiap elemen, dan grup yang isomorfik dapat dibuka di samping cincin lalu dikunci padanya dengan gembok, sehingga keduanya berputar, berwarna, dan tersorot sebagai satu.',
