      'formula.subgroupOrderLogLcm': '|⟨{h}⟩| = lcm(|{group}|, log_{g}({h})) / log_{g}({h}) = lcm({n}, log_{g}({g}^{q})) / log_{g}({g}^{q}) = lcm({n}, {q}) / {q} = {l} / {q} = {m}',
