      introAbout: 'Tigrawin tisutlanin ar sskarnt tagrawt d tawrirt n tnqqiḍin, yat tnqqiḍt i yal afrdis. Sti amuḍul d tamhlt — asmrni s umuḍul n, nɣ asgut n tyunitin s umuḍul n — tstit afrdis: iwtarn nns ar tteddun ɣ twrirt, d ticki wwḍn ɣr yal tanqqiḍt, afrdis ad ar isnulfu tagrawt akk, ayd ittgan tagrawt d tasutlant. Tawrirt ar tettar agdil, s tinbaḍin n tgrawt afella nns. Amuɣ amḍnan ar issken tagrawt tamẓẓit ittwasnlfn s yal afrdis, d tzmrt ad tldit yat tgrawt tamsalɣt ɣ tama n twrirt, tqqnt tt yid s uqfl, bac ad ttdwarnt, ad ttwaṣbɣnt d ad ttwakkanent am yat.',
