      isoLockOpenSub: 'ⵙⵉⵜ ⵙⵏⴰⵜ ⵏ ⵜⵉⴽⴽⴰⵍ ⴱⴰⵛ ⴰⴷ ⵜⵇⵇⵏⵜ ⵜⵉⴳⵔⴰⵡⵉⵏ ⵙ ⵓⵎⵙⴰⵍⵖ ⴳⵔ ⵜⴳⵔⴰⵡⵜ ⵜⴰⵎⵥⵥⵉⵜ ⴷ ⵜⴳⵔⴰⵡⵜ',
      introAbout: 'ⵜⵉⴳⵔⴰⵡⵉⵏ ⵜⵉⵙⵓⵜⵍⴰⵏⵉⵏ ⴰⵔ ⵙⵙⴽⴰⵔⵏⵜ ⵜⴰⴳⵔⴰⵡⵜ ⴷ ⵜⴰⵡⵔⵉⵔⵜ ⵏ ⵜⵏⵇⵇⵉⴹⵉⵏ, ⵢⴰⵜ ⵜⵏⵇⵇⵉⴹⵜ ⵉ ⵢⴰⵍ ⴰⴼⵔⴷⵉⵙ. ⵙⵜⵉ ⴰⵎⵓⴹⵓⵍ ⴷ ⵜⴰⵎⵀⵍⵜ — ⴰⵙⵎⵔⵏⵉ ⵙ ⵓⵎⵓⴹⵓⵍ n, ⵏⵖ ⴰⵙⴳⵓⵜ ⵏ ⵜⵢⵓⵏⵉⵜⵉⵏ ⵙ ⵓⵎⵓⴹⵓⵍ n — ⵜⵙⵜⵉⵜ ⴰⴼⵔⴷⵉⵙ: ⵉⵡⵜⴰⵔⵏ ⵏⵏⵙ ⴰⵔ ⵜⵜⴻⴷⴷⵓⵏ ⵖ ⵜⵡⵔⵉⵔⵜ, ⴷ ⵜⵉⵛⴽⵉ ⵡⵡⴹⵏ ⵖⵔ ⵢⴰⵍ ⵜⴰⵏⵇⵇⵉⴹⵜ, ⴰⴼⵔⴷⵉⵙ ⴰⴷ ⴰⵔ ⵉⵙⵏⵓⵍⴼⵓ ⵜⴰⴳⵔⴰⵡⵜ ⴰⴽⴽ, ⴰⵢⴷ ⵉⵜⵜⴳⴰⵏ ⵜⴰⴳⵔⴰⵡⵜ ⴷ ⵜⴰⵙⵓⵜⵍⴰⵏⵜ. ⵜⴰⵡⵔⵉⵔⵜ ⴰⵔ ⵜⴻⵜⵜⴰⵔ ⴰⴳⴷⵉⵍ, ⵙ ⵜⵉⵏⴱⴰⴹⵉⵏ ⵏ ⵜⴳⵔⴰⵡⵜ ⴰⴼⴻⵍⵍⴰ ⵏⵏⵙ. ⴰⵎⵓⵖ ⴰⵎⴹⵏⴰⵏ ⴰⵔ ⵉⵙⵙⴽⴻⵏ ⵜⴰⴳⵔⴰⵡⵜ ⵜⴰⵎⵥⵥⵉⵜ ⵉⵜⵜⵡⴰⵙⵏⵍⴼⵏ ⵙ ⵢⴰⵍ ⴰⴼⵔⴷⵉⵙ, ⴷ ⵜⵣⵎⵔⵜ ⴰⴷ ⵜⵍⴷⵉⵜ ⵢⴰⵜ ⵜⴳⵔⴰⵡⵜ ⵜⴰⵎⵙⴰⵍⵖⵜ ⵖ ⵜⴰⵎⴰ ⵏ ⵜⵡⵔⵉⵔⵜ, ⵜⵇⵇⵏⵜ ⵜⵜ ⵢⵉⴷ ⵙ ⵓⵇⴼⵍ, ⴱⴰⵛ ⴰⴷ ⵜⵜⴷⵡⴰⵔⵏⵜ, ⴰⴷ ⵜⵜⵡⴰⵚⴱⵖⵏⵜ ⴷ ⴰⴷ ⵜⵜⵡⴰⴽⴽⴰⵏⴻⵏⵜ ⴰⵎ ⵢⴰⵜ.',
