      introAbout: 'Greges cyclici gregem in anulum globulorum vertunt, unum globulum pro quoque elemento. Elige modulum et operationem — additionem modulo n, vel multiplicationem unitatum modulo n — deinde elige elementum: chordae eius circum anulum ambulant, et cum ad omnem globulum perveniunt, illud elementum totum gregem generat, quod gregem cyclicum facit. Anulus scrinium implet, imperiis gregis supra eum positis. Index Numericus subgregem quem quodque elementum generat ostendit, et grex isomorphus iuxta anulum aperiri et sera cum eo coniungi potest, ut ambo una vertantur, colorentur et illustrentur.',
